  function field(name,label,value='',type='text',dir='',required=true){return `<div class="field"><label for="${name}">${esc(label)}</label><input id="${name}" name="${name}" type="${type}" value="${value}" ${type==='number'?'step="any"':'maxlength="160"'} ${dir?`dir="${dir}"`:''} ${required?'required':''}></div>`;}
