  function mediaField(name,label,{onboarding=false,required=false}={}){const declared=state.bootstrap.capabilities?.privateMediaUploads??state.bootstrap.settings?.privateMediaUploadsEnabled,enabled=onboarding?declared!==false:Boolean(declared);return `<div class="field"><label for="${name}">${esc(label)}</label>${enabled?`<input id="${name}" name="${name}" type="file" accept="image/jpeg,image/png,image/webp,application/pdf" ${required?'required':''}>`:`<div class="info-box">${icon('camera')}<p>${tr('رفع الوسائط الخاصة غير مفعّل في هذا الخادم. لا يمكن ادعاء حفظ المستند دون تكامل حقيقي.','Private media upload is not enabled on this server. The document cannot be presented as saved without a real integration.')}</p></div>`}</div>`;}
