  function merchantProductActionDialog(productId,action){const product=(state.dashboard?.products||[]).find(item=>item.id===productId),branches=(state.dashboard?.branches||[]).filter(branch=>branch.id!==product?.branch_id),destructive=action==='archive';openDialog({title:({pause:tr('إيقاف المنتج مؤقتاً','Pause product'),resume:tr('استئناف المنتج','Resume product'),archive:tr('أرشفة المنتج','Archive product'),duplicate_to_branch:tr('نسخ المنتج إلى فرع','Copy product to branch')})[action]||tr('إدارة المنتج','Manage product'),eyebrow:esc(localized(product)),content:`<form id="merchantProductActionForm" class="form-grid"><input type="hidden" name="productId" value="${esc(productId)}"><input type="hidden" name="action" value="${esc(action)}">${action==='duplicate_to_branch'?`<div class="field"><label for="productTargetBranch">${tr('الفرع المستهدف','Target branch')}</label><select id="productTargetBranch" name="branchId" required>${branches.map(branch=>`<option value="${esc(branch.id)}">${esc(localized(branch))}</option>`).join('')}</select></div>`:`<div class="${destructive?'warning-box':'info-box'}">${icon(destructive?'alert':'info')}<p>${destructive?tr('تبقى بيانات المنتج في الطلبات السابقة، لكنه يختفي من الكتالوج النشط.','Historical orders keep the product snapshot, but it leaves the active catalog.'):tr('يسجل الخادم هذا التغيير ويعيد حالة المنتج الحالية.','The server records this change and returns the current product state.')}</p></div>`}<button class="${destructive?'danger-button':'primary-button'} full" type="submit">${tr('تأكيد الإجراء','Confirm action')}</button></form>`});}
