  async function adminReviewDialog(applicationId){openDialog({title:tr('مراجعة طلب متجر','Review merchant application'),eyebrow:esc(applicationId),wide:true,content:detailLoading()});try{const data=await api(`/api/admin/merchant-applications/${encodeURIComponent(applicationId)}`),content=$('.dialog-content',$('#overlayRoot'));if(content)content.innerHTML=adminApplicationReviewContent(data);}catch(error){const content=$('.dialog-content',$('#overlayRoot'));if(content)content.innerHTML=`<div class="error-state">${stateIcon('alert')}<h3>${tr('تعذر تحميل الطلب','Could not load application')}</h3><p>${esc(niceError(error))}</p></div>`;}}
  function adminApplicationReviewContent(data){const app=data.application||{},documents=data.documents||[],steps=data.steps||[],approvedKinds=new Set(documents.filter(doc=>doc.review_status==='approved').map(doc=>doc.kind)),canApprove=['storefront','commercial_registration','license'].every(kind=>approvedKinds.has(kind));return `<div class="data-list"><div class="data-row"><div><h3>${esc(localized(app,'merchant_name')||localized(app,'name')||app.id)}</h3><p>${statusText(app.status)} · ${steps.length} ${tr('خطوات محفوظة','saved steps')}</p></div><span class="status-pill">${esc(app.id||'')}</span></div></div><section class="section"><div class="section-head"><div><p class="eyebrow">${tr('ملفات خاصة','Private files')}</p><h3>${tr('مراجعة المستندات','Document review')}</h3></div><span class="status-pill ${canApprove?'approved':'pending'}">${canApprove?tr('مكتملة','Complete'):tr('تحتاج قراراً','Needs decisions')}</span></div><div class="warning-box">${icon('lock')}<p>${tr('تُجلب الملفات بتفويض الإدارة ورابط قصير العمر. لا تُرسل إلى واتساب ولا تتحول إلى رابط عام.','Files are fetched with admin authorization and a short-lived route. They are never sent to WhatsApp or made public.')}</p></div><div class="data-list section">${documents.length?documents.map(doc=>adminDocumentRow(app.id,doc)).join(''):compactEmpty('lock',tr('لا توجد مستندات مرتبطة','No documents are attached'))}</div></section><form id="adminDecisionForm" class="form-grid"><input type="hidden" name="applicationId" value="${esc(app.id||'')}"><div class="field"><label for="adminNote">${tr('ملاحظة القرار','Decision note')}</label><textarea id="adminNote" name="note" maxlength="1000"></textarea></div>${!canApprove?`<div class="info-box">${icon('info')}<p>${tr('يُتاح الاعتماد بعد اعتماد مستندات الواجهة والسجل والترخيص.','Approval is enabled after storefront, CR and licence documents are approved.')}</p></div>`:''}<div class="form-actions"><button class="primary-button" name="decision" value="approve" ${canApprove?'':'disabled'}>${tr('اعتماد','Approve')}</button><button class="secondary-button" name="decision" value="changes_requested">${tr('طلب تحديث','Request changes')}</button><button class="danger-button" name="decision" value="reject">${tr('رفض','Reject')}</button></div></form>`;}
  function adminDocumentRow(applicationId,document){const status=document.review_status||'pending',size=numberValue(document.byte_size),name=document.original_name||document.kind;return `<article class="data-row admin-document-row"><div><span class="status-pill ${status==='approved'?'approved':status==='rejected'?'danger':'pending'}">${adminDocumentStatus(status)}</span><h3>${esc(documentKindLabel(document.kind))}</h3><p>${esc(name)} · ${size?`${(size/1024).toFixed(1)} KB`:''} ${esc(document.mime_type||'')}</p></div><div class="row-actions"><button class="quiet-button" data-admin-document-open="${esc(document.media_id)}">${icon('search')}${tr('فتح','Open')}</button><button class="primary-button" data-admin-document-decision="approve" data-application-id="${esc(applicationId)}" data-document-id="${esc(document.id)}">${tr('اعتماد','Approve')}</button><button class="danger-button" data-admin-document-decision="reject" data-application-id="${esc(applicationId)}" data-document-id="${esc(document.id)}">${tr('رفض','Reject')}</button></div></article>`;}
