  function adminDocumentStatus(status){return ({approved:tr('معتمد','Approved'),rejected:tr('مرفوض','Rejected'),pending:tr('بانتظار المراجعة','Pending review')})[status]||status;}
  function adminDocumentDecisionDialog(applicationId,documentId,decision){openDialog({title:decision==='approve'?tr('اعتماد المستند','Approve document'):tr('رفض المستند','Reject document'),eyebrow:tr('قرار مسجّل في التدقيق','Audited decision'),content:`<form id="adminDocumentDecisionForm" class="form-grid"><input type="hidden" name="applicationId" value="${esc(applicationId)}"><input type="hidden" name="documentId" value="${esc(documentId)}"><input type="hidden" name="decision" value="${esc(decision)}"><div class="field"><label for="documentDecisionNote">${tr('ملاحظة المراجع','Reviewer note')}</label><textarea id="documentDecisionNote" name="note" maxlength="500" ${decision==='reject'?'required':''}></textarea></div><button class="${decision==='approve'?'primary-button':'danger-button'} full" type="submit">${decision==='approve'?tr('اعتماد المستند','Approve document'):tr('رفض وإرسال الملاحظة','Reject and send note')}</button></form>`});}
