  const BRANCH_DAY_OPTIONS=[['sat','السبت','Sat'],['sun','الأحد','Sun'],['mon','الاثنين','Mon'],['tue','الثلاثاء','Tue'],['wed','الأربعاء','Wed'],['thu','الخميس','Thu'],['fri','الجمعة','Fri']];
  function branchHoursValue(branch){return parseObject(branch?.hours||branch?.hours_json||{},{});}
  function branchHoursFields(hours={}){const entries=Object.entries(hours).filter(([,value])=>value==='24h'||(Array.isArray(value)&&value.length)),selected=new Set(entries.map(([day])=>day)),first=entries[0]?.[1],slot=Array.isArray(first)?first[0]:null,open=first==='24h'?'00:00':slot?.open||'09:00',close=first==='24h'?'23:59':slot?.close||'21:00';return `<fieldset class="field"><legend>${tr('أيام العمل','Working days')}</legend><div class="chip-row">${BRANCH_DAY_OPTIONS.map(([id,ar,en])=>`<label class="chip"><input type="checkbox" name="branchWorkDays" value="${id}" ${selected.size?selected.has(id)?'checked':'':['sat','sun','mon','tue','wed','thu'].includes(id)?'checked':''}> ${tr(ar,en)}</label>`).join('')}</div></fieldset><div class="form-row"><div class="field"><label for="branchOpenTime">${tr('يفتح','Opens')}</label><input id="branchOpenTime" name="branchOpenTime" type="time" value="${esc(open)}" required></div><div class="field"><label for="branchCloseTime">${tr('يغلق','Closes')}</label><input id="branchCloseTime" name="branchCloseTime" type="time" value="${esc(close)}" required></div></div>`;}
  function branchHoursFromForm(fd){const days=new Set(fd.getAll('branchWorkDays')),open=String(fd.get('branchOpenTime')||''),close=String(fd.get('branchCloseTime')||'');if(!days.size||!/^\d{2}:\d{2}$/.test(open)||!/^\d{2}:\d{2}$/.test(close)||open===close)throw Object.assign(new Error('valid_opening_hours_required'),{code:'valid_opening_hours_required'});return Object.fromEntries(BRANCH_DAY_OPTIONS.map(([day])=>[day,days.has(day)?[{open,close}]:[]]));}
