    openDialog({title:locked?tr('الفرع قيد المراجعة','Branch under review'):tr('إرسال الفرع للمراجعة','Submit branch for review'),eyebrow:`${statusText(current.status)} · ${localized(current)}`,wide:true,content:`<div class="data-list"><article class="data-row"><div><p>${tr('الموقع','Location')}</p><h3>${esc(current.address||addressText(current))}</h3><p class="ltr-number">${esc(current.latitude??'—')}, ${esc(current.longitude??'—')}</p></div></article>${documentRows}</div>${locked?`<div class="info-box">${icon('clock')}<p>${tr('لا يمكن تغيير الملف أثناء قرار المراجع.','The submission is locked while a reviewer decides.')}</p></div>`:`<form id="merchantBranchLaunchForm" class="form-grid"><input type="hidden" name="branchId" value="${esc(current.id)}"><input type="hidden" name="existingDocuments" value="${esc(encodeURIComponent(JSON.stringify(documents.map(doc=>({kind:doc.kind,mediaId:doc.mediaId})))))}"><div class="field"><label for="branchStorefrontFile">${tr('صورة واجهة الفرع','Branch storefront image')}</label><input id="branchStorefrontFile" name="storefrontFile" type="file" accept="image/jpeg,image/png,image/webp,application/pdf" ${documents.some(doc=>doc.kind==='storefront')?'':'required'}></div><div class="field"><label for="branchDocumentException">${tr('سبب استثناء المستند — عند التعذر فقط','Document exception reason — only when unavailable')}</label><textarea id="branchDocumentException" name="documentExceptionReason" maxlength="500">${esc(detail.submission?.documentExceptionReason||'')}</textarea></div>${branchHoursFields(current.hours||branchHoursValue(current))}<button class="primary-button full" type="submit">${tr('إرسال للمراجعة','Submit for review')}</button></form>`}`});
