      openDialog({title:tr('مراجعة حملة المورد','Review supplier campaign'),eyebrow:`${statusText(campaign.status)} · ${campaign.id}`,wide:true,content:`<div class="campaign-review"><div class="media-frame"><img src="${esc(objectUrl)}" alt="${esc(localized(campaign,'title'))}"></div><div class="data-list"><article class="data-row"><div><p>${tr('العنوان والوصف','Title and description')}</p><h3>${esc(localized(campaign,'title'))}</h3><p>${esc(localized(campaign,'wholesaleDescription'))}</p></div></article><article class="data-row"><div><p>${tr('العرض والحد الأدنى','Offer and minimum order')}</p><h3>${esc(localized(campaign,'offer'))}</h3><p>${numberValue(campaign.minimumOrderQuantity)} ${tr('وحدة كحد أدنى','units minimum')}</p></div></article><article class="data-row"><div><p>${tr('الاستهداف','Targeting')}</p><h3>${esc(names(campaign.targetCategories,categories))}</h3><p>${esc(names([...(campaign.targetWilayats||[]),...(campaign.targetAreas||[])],locations))}</p></div></article><article class="data-row"><div><p>${tr('الفترة','Schedule')}</p><h3>${formatDate(campaign.startsAt)} — ${formatDate(campaign.endsAt)}</h3><p>${esc(localized(campaign,'terms'))}</p></div></article></div><form id="adminModerationForm" class="form-grid"><input type="hidden" name="resource" value="supplier_campaign"><input type="hidden" name="id" value="${esc(campaign.id)}"><div class="field"><label for="moderationReason">${tr('سبب القرار — يصل للمورد','Decision reason — shared with supplier')}</label><textarea id="moderationReason" name="reason" maxlength="500" ${['pending_review','approved'].includes(campaign.status)?'required':'disabled'}></textarea></div><div class="form-actions">${reviewActions}</div></form></div>`});
