  async function submitLogin(form){const button=$('button[type="submit"]',form);button.disabled=true;try{saveAuth(await api('/api/auth',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(form)))}));closeDialog();toast(tr('أهلاً بك في BISA','Welcome to BISA'));await loadApp();if(state.account?.role==='shopper'){const merged=await mergeGuestCart(false),postLogin=sessionStorage.getItem(STORAGE.postLogin);if(merged&&postLogin==='checkout'){sessionStorage.removeItem(STORAGE.postLogin);navigate('cart');checkoutDialog();}}}catch(error){showFormError(form,niceError(error));button.disabled=false;}}
  function showFormError(form,message){let node=$('.field-error',form);if(!node){node=document.createElement('p');node.className='field-error';node.setAttribute('role','alert');form.prepend(node);}node.textContent=message;}
  function addGuestCart(payload){const entity=guestCatalogItem(payload.kind,payload.itemId,payload.branchId);if(!entity)return toast(tr('لم يعد هذا المنتج متاحاً','This item is no longer available'),'error');let record=guestCartRecord();if(record.items.length&&record.branchId!==payload.branchId&&!payload.replaceCart)return crossStoreDialog(payload,{detail:{currentMerchantId:state.bootstrap.cart?.merchant_id,newMerchantId:entity.merchant_id}});if(payload.replaceCart||!record.items.length)record={branchId:payload.branchId,items:[]};const existing=record.items.find(item=>item.kind===payload.kind&&item.itemId===payload.itemId);if(existing)existing.quantity=Math.min(100,existing.quantity+Math.max(1,numberValue(payload.quantity)));else record.items.push({kind:payload.kind,itemId:payload.itemId,branchId:payload.branchId,quantity:Math.max(1,numberValue(payload.quantity))});saveGuestCart(record);hydrateGuestCart();toast(tr('أُضيف إلى السلة','Added to cart'));render();fireAnalytics('add_to_cart',payload.kind,payload.itemId,{branchId:payload.branchId||'',guest:true});}
  async function addToCart(payload){if(!state.account)return addGuestCart(payload);const request={...payload,expectedVersion:state.bootstrap.cart?.version??0};try{state.bootstrap.cart=await apiFallback('/api/cart/items','/api/cart',{method:'POST',body:JSON.stringify(request)});toast(tr('أُضيف إلى السلة','Added to cart'));render();fireAnalytics('add_to_cart',payload.kind,payload.itemId,{branchId:payload.branchId||''});}catch(error){if(error.code==='cross_store_cart_confirmation_required')return crossStoreDialog(payload,error);toast(niceError(error),'error');}}
  async function mergeGuestCart(replaceServer=false){const record=guestCartRecord();if(!record.items.length)return true;for(let index=0;index<record.items.length;){const item=record.items[index];try{state.bootstrap.cart=await api('/api/cart/items',{method:'POST',body:JSON.stringify({...item,expectedVersion:state.bootstrap.cart?.version??0,replaceCart:replaceServer&&index===0})});record.items.splice(index,1);saveGuestCart(record);replaceServer=false;}catch(error){if(error.code==='cross_store_cart_confirmation_required'){guestMergeConflictDialog();return false;}toast(niceError(error),'error');return false;}}localStorage.removeItem(STORAGE.guestCart);toast(tr('تمت مزامنة سلة الضيف','Guest cart synced'));render();return true;}
  async function updateCart(button){const item=(state.bootstrap.cart?.items||[]).find(row=>row.item_kind===button.dataset.itemKind&&row.item_id===button.dataset.itemId),current=numberValue(item?.quantity),action=button.dataset.cartAction,next=action==='remove'?0:action==='increment'?current+1:Math.max(0,current-1);button.disabled=true;if(!state.account){const record=guestCartRecord(),saved=record.items.find(row=>row.kind===button.dataset.itemKind&&row.itemId===button.dataset.itemId);if(saved){if(next<=0)record.items=record.items.filter(row=>row!==saved);else saved.quantity=next;}saveGuestCart(record);hydrateGuestCart();render();return;}const payload={quantity:next,expectedVersion:state.bootstrap.cart?.version??0};try{state.bootstrap.cart=await api(`/api/cart/items/${encodeURIComponent(button.dataset.itemKind)}/${encodeURIComponent(button.dataset.itemId)}`,{method:'PUT',body:JSON.stringify(payload)});render();}catch(error){toast(niceError(error),'error');button.disabled=false;}}
