  function onboardingPayload(key,data){
    if(key==='owner')return {contactName:data.contactName,contactPhone:data.contactPhone,authorizedRole:data.authorizedRole};
    if(key==='business')return {nameAr:data.nameAr,nameEn:data.nameEn,merchantType:data.merchantType||'store',commercialRegistration:data.commercialRegistration};
    if(key==='brand')return {logoMediaId:data.logoMediaId||'',coverMediaId:data.coverMediaId||''};
    if(key==='location')return {branchNameAr:data.branchNameAr,branchNameEn:data.branchNameEn,wilayahId:data.wilayahId,areaId:data.areaId,addressText:data.addressText,latitude:data.latitude===''||data.latitude==null?null:Number(data.latitude),longitude:data.longitude===''||data.longitude==null?null:Number(data.longitude)};
    if(key==='hours'){const selected=new Set(Array.isArray(data.workDays)?data.workDays:[]),open=data.openTime,close=data.closeTime;if(!selected.size||!/^(?:[01]\d|2[0-3]):[0-5]\d$/.test(open)||!/^(?:[01]\d|2[0-3]):[0-5]\d$/.test(close)||open===close)throw Object.assign(new Error('valid_opening_hours_required'),{code:'valid_opening_hours_required',status:422});return {hours:Object.fromEntries(['mon','tue','wed','thu','fri','sat','sun'].map(day=>[day,selected.has(day)?[{open,close}]:[]]))};}
    if(key==='documents')return {documents:[['storefront',data.storefrontMediaId],['commercial_registration',data.commercialRegistrationMediaId],['license',data.licenseMediaId]].map(([kind,mediaId])=>({kind,mediaId}))};
    if(key==='fulfillment')return {pickup:{enabled:Boolean(data.pickupEnabled),feeBaisa:0,minimumBaisa:0,freeThresholdBaisa:0},office:{enabled:Boolean(data.officeEnabled),feeBaisa:omrInputToBaisa(data.officeFee),minimumBaisa:0,freeThresholdBaisa:0},home:{enabled:Boolean(data.homeEnabled),feeBaisa:omrInputToBaisa(data.homeFee),minimumBaisa:0,freeThresholdBaisa:0},zones:[],eta:''};
    if(key==='policy')return {returnWindowDays:Number(data.returnWindowDays||0),exchangeWindowDays:Number(data.exchangeWindowDays||0),conditions:data.conditions,receiptRequired:Boolean(data.receiptRequired),excludedCategories:[],contactMethod:data.contactMethod,notes:''};
    if(key==='categories')return {categoryIds:Array.isArray(data.categoryIds)?data.categoryIds:[]};
    if(key==='plan')return {planId:data.planId};
    if(key==='review')return {acceptedPolicies:Boolean(data.acceptedPolicies)};
    return {};
  }
  function omrInputToBaisa(value){const amount=Number(String(value||'0').replace(',','.'));return Number.isFinite(amount)?Math.max(0,Math.round(amount*1000)):0;}
  async function uploadPrivateMedia(file,ownerKind,ownerId,purpose){
    if(!(file instanceof File)||!file.size)return '';
    if(file.size>10*1024*1024)throw Object.assign(new Error('private_media_too_large'),{code:'private_media_too_large',status:413});
    const filename=encodeURIComponent(file.name||'upload').slice(0,180);
    const result=await api('/api/private-media',{method:'POST',headers:{'Content-Type':file.type||'application/octet-stream','X-BISA-Owner-Kind':ownerKind,'X-BISA-Owner-Id':ownerId,'X-BISA-Purpose':purpose,'X-BISA-Filename':filename},body:file});
    return result.media?.id||'';
  }
